CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "tenantKey" TEXT, "openId" TEXT, "displayName" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "User_tenantKey_openId_key" ON "User"("tenantKey", "openId");
CREATE TABLE "Job" ("id" UUID PRIMARY KEY, "userId" TEXT NOT NULL, "scene" TEXT NOT NULL, "status" TEXT NOT NULL, "currentStep" TEXT, "previousJobId" UUID, "idempotencyKey" TEXT NOT NULL, "schemaVersion" TEXT NOT NULL DEFAULT '1', "deletedAt" TIMESTAMP(3), "purgeAfter" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Job_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Job_idempotencyKey_key" ON "Job"("idempotencyKey"); CREATE INDEX "Job_userId_updatedAt_idx" ON "Job"("userId", "updatedAt"); CREATE INDEX "Job_previousJobId_idx" ON "Job"("previousJobId"); CREATE INDEX "Job_purgeAfter_idx" ON "Job"("purgeAfter");
CREATE TABLE "JobPayload" ("jobId" UUID PRIMARY KEY, "schemaVersion" TEXT NOT NULL, "data" JSONB NOT NULL, CONSTRAINT "JobPayload_jobId_fkey" FOREIGN KEY ("jobId") REFERENCES "Job"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "VisualAsset" ("id" TEXT PRIMARY KEY, "jobId" UUID NOT NULL, "ownerId" TEXT NOT NULL, "kind" TEXT NOT NULL, "objectKey" TEXT NOT NULL, "contentType" TEXT NOT NULL, "width" INTEGER, "height" INTEGER, "provider" TEXT, "model" TEXT, "status" TEXT NOT NULL, "selected" BOOLEAN NOT NULL DEFAULT false, "expiresAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "VisualAsset_jobId_fkey" FOREIGN KEY ("jobId") REFERENCES "Job"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "VisualAsset_objectKey_key" ON "VisualAsset"("objectKey"); CREATE INDEX "VisualAsset_jobId_idx" ON "VisualAsset"("jobId"); CREATE INDEX "VisualAsset_ownerId_createdAt_idx" ON "VisualAsset"("ownerId", "createdAt"); CREATE INDEX "VisualAsset_expiresAt_idx" ON "VisualAsset"("expiresAt");
CREATE TABLE "PosterOutput" ("id" TEXT PRIMARY KEY, "jobId" UUID NOT NULL, "ownerId" TEXT NOT NULL, "objectKey" TEXT NOT NULL, "contentType" TEXT NOT NULL, "width" INTEGER NOT NULL, "height" INTEGER NOT NULL, "templateVersion" TEXT NOT NULL, "validation" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PosterOutput_jobId_fkey" FOREIGN KEY ("jobId") REFERENCES "Job"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "PosterOutput_objectKey_key" ON "PosterOutput"("objectKey"); CREATE INDEX "PosterOutput_jobId_idx" ON "PosterOutput"("jobId"); CREATE INDEX "PosterOutput_ownerId_createdAt_idx" ON "PosterOutput"("ownerId", "createdAt");
CREATE TABLE "JobAction" ("id" UUID PRIMARY KEY, "jobId" UUID NOT NULL, "idempotencyKey" TEXT NOT NULL, "action" TEXT NOT NULL, "status" TEXT NOT NULL, "error" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "JobAction_jobId_fkey" FOREIGN KEY ("jobId") REFERENCES "Job"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "JobAction_idempotencyKey_key" ON "JobAction"("idempotencyKey"); CREATE INDEX "JobAction_jobId_createdAt_idx" ON "JobAction"("jobId", "createdAt");
CREATE TABLE "StorageCleanup" ("objectKey" TEXT PRIMARY KEY, "reason" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
